    <div class="setting-item">
      <div class="setting-info">
        <div class="setting-title">段评样式</div>
        <div class="setting-desc">选择段评显示的样式风格，下方可实时预览效果</div>
      </div>
      <div class="select-wrapper">
        <select id="duanpingStyle">
          <option value="0">起点样式</option>
          <option value="1">番茄样式</option>
          <option value="2">精致样式</option>
          <option value="3">对话样式</option>
          <option value="4">方框样式</option>
          <option value="5">圆圈样式</option>
        </select>
      </div>
    </div>

    <div class="setting-item">
      <div class="setting-info">
        <div class="setting-title">边框颜色</div>
