function qmC_GodImage(bid, cid, pid, gid, text, paragraphText) {
  text = String(text || '').replace(/[\r\n]+/g, ' ').trim();
  if (!gid || !text) return '';
  if (text.length > 18) text = text.slice(0, 18) + '...';
  var svg = '<svg width="1000" height="120" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="0" width="996" height="100" fill="rgba(255,255,255,0.25)" rx="35" stroke="#444" stroke-width="1"/><rect x="32" y="22" width="140" height="56" rx="20" fill="#000"/><text x="102" y="64" font-size="32" font-family="Arial" fill="#FFF" text-anchor="middle" font-weight="bold">神评</text><text x="196" y="64" font-size="38" font-family="Arial" fill="#111" font-weight="bold">' + qmC_Esc(text) + '</text></svg>';
