  var encoded = String(runtimeJava.base64Encode(svg)).replace(/[=\r\n]/g, '');
  var call = 'qmC_OpenComment(' + JSON.stringify('chapter') + ',' + JSON.stringify(String(bid)) + ',' + JSON.stringify(String(cid)) + ',' + JSON.stringify('') + ',' + JSON.stringify('本章说') + ')';
  return '<img src="data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify({style:'FULL',type:'qmpl-chapter-preview',click:call}) + '">';
}
function qmC_AppendComments(text, bid, cid, cmd5) {
  var lines = String(text == null ? '' : text).split('\n');
  var settings = qmC_DisplaySettings.call(this);
  var marks = (settings.paragraph || settings.god) ? qmC_ParagraphBubbles.call(this, bid, cid, cmd5) : {};
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (!line) continue;
    var hash = qmC_Md5.call(this, line);
    if (!hash) continue;
    var pid = hash.slice(0, 8);
    var mark = marks[pid];
    if (!mark) continue;
    if (settings.paragraph && Number(mark.count) > 0) {
      var img = qmC_BubbleSvg.call(this, mark.count, mark.hot, mark.hot ? '热门段评' : '七猫段评');
      var call = 'qmC_OpenComment(' + JSON.stringify('paragraph') + ',' + JSON.stringify(String(bid)) + ',' + JSON.stringify(String(cid)) + ',' + JSON.stringify(String(pid)) + ',' + JSON.stringify('七猫段评') + ',' + JSON.stringify(String(line)) + ')';
      lines[i] += '<img src="' + img + ',' + JSON.stringify({style:'text',type:'qmpl',click:call}) + '">';
    }
    var god = settings.god ? qmC_GodImage.call(this, bid, cid, pid, mark.gid, mark.gtxt, line) : '';
    if (god) lines[i] += '\n' + god;
  }
  if (settings.chapter) {
    var preview = qmC_ChapterPreviewImage.call(this, bid, cid);
    if (preview) lines.push(preview);
  }
  return lines.join('\n');
}

